import {
    Object3D,
    Mesh,
    PlaneGeometry,
    DoubleSide,
    Color,
} from 'three/webgpu';
import {
    MeshBasicNodeMaterial,
    texture,
} from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import { createTextMesh } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} [position]
 * @property {{x:number,y:number,z:number}} [rotation] // degrees
 * @property {{x:number,y:number,z:number}} [scale]
 * @property {{imageUrl:string}} [assets]
 * @property {Array<{name:string,params:any}>} [cinematicPrimitives]
 * @property {Array<{text:string,role:string}>} [textContent]
 * @property {{width:number,height:number}} [atlasRegion]
 * @property {any} [userData]
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>import('three').Texture} textureLoader
 * @property {{fontAtlas:any}} fontAtlas
 * @property {{[key:string]:(target:import('three').Object3D, params:any)=>void}} primitives
 */

/**
 * Creates a textured plane with a headline rendered via MSDF.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
    // -------------------------------------------------------------------------
    // Root Object3D – apply placement transform
    // -------------------------------------------------------------------------
    const root = new Object3D();

    if (config.position) {
        root.position.set(config.position.x, config.position.y, config.position.z);
    }
    if (config.rotation) {
        const deg2rad = Math.PI / 180;
        root.rotation.set(
            (config.rotation.x ?? 0) * deg2rad,
            (config.rotation.y ?? 0) * deg2rad,
            (config.rotation.z ?? 0) * deg2rad,
        );
    }
    if (config.scale) {
        root.scale.set(config.scale.x, config.scale.y, config.scale.z);
    }

    // -------------------------------------------------------------------------
    // Textured Plane
    // -------------------------------------------------------------------------
    const tex = ctx.textureLoader(config.assets?.imageUrl);
    const planeGeom = new PlaneGeometry(1, 1);
    const mapNode = texture(tex);
    const planeMat = new MeshBasicNodeMaterial({
        map: mapNode,
        side: DoubleSide,
        transparent: true,
    });
    const planeMesh = new Mesh(planeGeom, planeMat);
    // Scale to match the intended pixel dimensions (using a simple 100px → 1 unit factor)
    const region = config.atlasRegion || { width: 512, height: 320 };
    planeMesh.scale.set(region.width / 100, region.height / 100, 1);
    root.add(planeMesh);

    // -------------------------------------------------------------------------
    // MSDF Headline Text
    // -------------------------------------------------------------------------
    const headlineSpec = (config.textContent || []).find(t => t.role === 'headline') ||
        { text: 'Collection' };
    const textMesh = createTextMesh(headlineSpec.text, {
        fontAtlas: ctx.fontAtlas,
        color: new Color('#16161d'), // ink
        // headline scale from design tokens (0.34 scene‑unit em height)
        size: 0.34,
        // simple centering on plane
        anchorX: 0.5,
        anchorY: 0.5,
    });
    // Lift a little forward so it renders above the texture
    textMesh.position.set(0, 0, 0.01);
    root.add(textMesh);

    // -------------------------------------------------------------------------
    // Apply Cinematic Primitives (if any)
    // -------------------------------------------------------------------------
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const prim of config.cinematicPrimitives) {
            const fn = ctx.primitives[prim.name];
            if (typeof fn === 'function') {
                fn(root, prim.params);
            }
        }
    }

    // -------------------------------------------------------------------------
    // User‑Data – Handlers placeholder
    // -------------------------------------------------------------------------
    root.userData.handlers = {};

    // -------------------------------------------------------------------------
    // Cleanup – dispose resources and kill GSAP timelines
    // -------------------------------------------------------------------------
    root.userData.cleanup = () => {
        planeGeom.dispose();
        tex.dispose();
        planeMat.dispose();
        if (typeof textMesh.userData?.cleanup === 'function') {
            textMesh.userData.cleanup();
        }
        gsap.globalTimeline.clear();
    };

    return root;
}
